window.__votdWeek && window.__votdWeek({"week":"2029-11-19","reading":"Doctrine and Covenants 133–134","days":[{"d":"2029-11-19","ref":"D&C 133:5","b":"D&C","c":133,"v":5,"he":"צְאוּ מִבָּבֶל הִבָּרוּ נֹשְׂאֵי כְּלֵי יְהוָה׃","en":"Go ye out from Babylon. Be ye clean that bear the vessels of the Lord."},{"d":"2029-11-20","ref":"D&C 133:22","b":"D&C","c":133,"v":22,"he":"וְהָיָה קוֹלוֹ כְּקוֹל מַיִם רַבִּים וּכְקוֹל רַעַם גָּדוֹל אֲשֶׁר יְנַתֵּץ הֶהָרִים וְהָעֲמָקִים לֹא יִמָּצֵאוּ׃","en":"And it shall be a voice as the voice of many waters, and as the voice of a great thunder, which shall break down the mountains, and the valleys shall not be found."},{"d":"2029-11-21","ref":"D&C 133:58","b":"D&C","c":133,"v":58,"he":"לְהָכִין אֶת־הַחַלָּשִׁים לַדְּבָרִים הַבָּאִים עַל הָאָרֶץ וְלִשְׁלִיחוּת יְהוָה בַּיּוֹם אֲשֶׁר הַחַלָּשִׁים יָבִישׁוּ אֶת־הַחֲכָמִים וְהַקָּטֹן יִהְיֶה לְגוֹי עָצוּם וּשְׁנַיִם יָנִיסוּ רְבָבוֹת׃","en":"To prepare the weak for those things which are coming on the earth, and for the Lord's errand in the day when the weak shall confound the wise, and the little one become a strong nation, and two shall put their tens of thousands to flight."},{"d":"2029-11-22","ref":"D&C 133:63","b":"D&C","c":133,"v":63,"he":"וְעַל אֲשֶׁר לֹא יִשְׁמְעוּ לְקוֹל יְהוָה יְקֻיַּם הַכָּתוּב בְּיַד מֹשֶׁה הַנָּבִיא כִּי יִכָּרְתוּ מִתּוֹךְ הָעָם׃","en":"And upon them that hearken not to the voice of the Lord shall be fulfilled that which was written by the prophet Moses, that they should be cut off from among the people."},{"d":"2029-11-23","ref":"D&C 134:1","b":"D&C","c":134,"v":1,"he":"מַאֲמִינִים אֲנַחְנוּ כִּי הַמֶּמְשָׁלוֹת נוֹסְדוּ מֵאֵת אֱלֹהִים לְטוֹבַת הָאָדָם וְכִי הוּא מְבַקֵּשׁ מִן הָאָדָם חֶשְׁבּוֹן עַל מַעֲשֵׂיהֶן בִּדְבָרָן גַּם בְּחֻקּוֹתֵיהֶן וּבְהַנְהָגָתָן לְטוֹבַת וּלְשַׁלְוַת הַחֶבְרָה׃","en":"We believe that governments were instituted of God for the benefit of man; and that he holds men accountable for their acts in relation to them, both in making laws and administering them, for the good and safety of society."},{"d":"2029-11-24","ref":"D&C 134:2","b":"D&C","c":134,"v":2,"he":"מַאֲמִינִים אֲנַחְנוּ כִּי אֵין מֶמְשָׁלָה יְכוֹלָה לַעֲמֹד בְּשָׁלוֹם כִּי־אִם חֻקִּים יֵחָקְקוּ וְנִשְׁמְרוּ בְּלֹא־הֵפֵר אֲשֶׁר יַבְטִיחוּ לְכׇל אִישׁ אֶת־חֵרוּת הַלֵּב וְאֶת־זְכוּת הַקִּנְיָן וּרְשׁוּתוֹ עָלָיו וְאֶת־מִשְׁמֶרֶת הַנֶּפֶשׁ׃","en":"We believe that no government can exist in peace, except such laws are framed and held inviolate as will secure to each individual the free exercise of conscience, the right and control of property, and the protection of life."},{"d":"2029-11-25","ref":"D&C 134:9","b":"D&C","c":134,"v":9,"he":"אֵין אָנוּ מַאֲמִינִים כִּי צֶדֶק הוּא לְעָרֵב כֹּחַ דָּתִי בְּמֶמְשֶׁלֶת מְדִינָה אֲשֶׁר בָּהּ עֵדָה דָתִית אַחַת תְּנֻשֵּׂא וְאַחֶרֶת תְּדֻכֶּה בִּזְכֻיּוֹתֶיהָ הָרוּחָנִיּוֹת וּזְכֻיּוֹת יְחִידֶיהָ כְּיוֹשְׁבִים נִמְנָעוֹת׃","en":"We do not believe it just to mingle religious influence with civil government, whereby one religious society is fostered and another proscribed in its spiritual privileges, and the individual rights of its members, as citizens, denied."}]});
